window.FILM_WORK_PROMPTS={"work_id":"src-bac6c76a669a62af","records":[{"work_id":"src-bac6c76a669a62af","frame_id":"FG-8e53a9e3c20ea39b","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Border_007.jpg","source_page":"https://film-grab.com/2022/04/21/border/","scene":"画面右下角为仰视角度的人物面部特写，背景是密集且虚化的垂直树林，人物头部占据画面约四分之一，其余为森林环境。","analysis":"构图将人物置于右下角，大面积留白给背景森林。人物仅可见面部及少许头发，头部后仰，视线向上。背景树木呈垂直线条状，因景深效果而模糊，形成散景。光线从上方透过树冠洒下，形成明暗对比，整体色调偏冷绿，人物面部受光柔和，细节清晰。","prompt":"画面右下角呈现一名人物的面部特写，头部大幅度后仰，视线朝向左上方，嘴巴微张，神情显得紧张或惊恐。人物面部皮肤纹理清晰，光线从上方投射，照亮了面部轮廓。背景是一片茂密的森林，无数垂直的树干在景深作用下变得模糊，形成绿色的散景光斑。整体色调为冷绿色，营造出幽深、压抑的森林氛围，人物与背景形成清晰的虚实对比。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T17:29:32-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Border_007.jpg","observed_dimensions":[1280,537],"source_thumbnail_dimensions":[500,210],"source_image_match_mae":0.505,"observed_resolution":"normal","observation_limits":[],"id":"VP-c45c2b4d47dc8cd2","origin":"visual"},{"work_id":"src-bac6c76a669a62af","frame_id":"FG-714a19c38019d432","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Border_019.jpg","source_page":"https://film-grab.com/2022/04/21/border/","scene":"一名裸体人物站立在幽暗森林深处的水潭中，右侧有瀑布注入，四周被茂密树木和昏暗的林地包围。","analysis":"人物位于画面中央偏下，全身可见，呈站立姿态，身体在暗色水面形成倒影。环境占据绝大部分画面，树木和植被形成深色背景。整体光线昏暗，冷色调为主，右侧瀑布提供局部亮区，人物肤色在暗环境中形成对比。","prompt":"幽暗森林深处，一名裸体人物全身站立在深色水潭中，水面平静有倒影，人物位于画面中央偏下位置。右侧有白色瀑布从岩石倾泻注入水潭，形成局部亮区。四周被高大树木和茂密绿色植被包围，背景林地昏暗，地面覆盖落叶和草丛。整体冷色调，光线微弱，人物肤色与暗色环境形成明暗对比，水面散布细小气泡或碎屑。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T17:29:38-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Border_019.jpg","observed_dimensions":[1280,537],"source_thumbnail_dimensions":[500,210],"source_image_match_mae":0.514,"observed_resolution":"normal","observation_limits":[],"id":"VP-06fdfbf5fffcf46e","origin":"visual"},{"work_id":"src-bac6c76a669a62af","frame_id":"FG-9c430b0313c96b7b","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Border_032.jpg","source_page":"https://film-grab.com/2022/04/21/border/","scene":"昏暗环境中，两名人物面对面近距离相对，左侧人物面部朝向右侧，右侧人物侧脸朝向左侧，背景深处隐约可见模糊的人脸轮廓，整体氛围压抑。","analysis":"画面以两名人物面部及上半身为主，占据画面左右两侧，中间留有暗部空间。左侧人物头发较长，面部受光较多，右侧人物仅见侧脸轮廓。背景极暗，中央深处有一张模糊面孔。光线呈冷青绿色调，明暗对比强烈，人物面部有局部高光，其余部分沉入阴影，营造出幽闭、紧张的空间感。","prompt":"昏暗幽闭空间内，两名人物近距离面对面相对。左侧人物头发较长且凌乱，面部朝向右侧，神情紧绷，面部受冷青色光照亮，可见上半身轮廓。右侧人物仅露出侧脸，头发较短，面向左侧，面部大部分处于阴影中，仅鼻梁和嘴唇边缘有微弱反光。两人之间背景极暗，深处隐约浮现一张模糊的人脸轮廓。整体色调为深青绿色，明暗对比强烈，光源似乎来自画面外侧，在人物面部形成局部高光，其余部分沉入浓重阴影，空间感压抑而紧张。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T17:29:45-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Border_032.jpg","observed_dimensions":[1280,537],"source_thumbnail_dimensions":[500,210],"source_image_match_mae":0.36,"observed_resolution":"normal","observation_limits":[],"id":"VP-31cf23e62823f591","origin":"visual"},{"work_id":"src-bac6c76a669a62af","frame_id":"FG-e30f11d00d9d882a","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Border_044.jpg","source_page":"https://film-grab.com/2022/04/21/border/","scene":"昏暗的森林湖泊中，两个模糊的人影头部露出水面，背景是茂密幽暗的树林，水面平静且色调阴冷。","analysis":"画面采用横向构图，两个极小的人影位于画面中下部，仅露出头部和少许肩部，与广阔的水面和背景树林形成强烈的大小对比。镜头视角平视，光线昏暗，整体呈现冷绿色调，背景树林细节模糊，营造出一种压抑、神秘且静谧的视觉氛围。","prompt":"这是一张色调阴冷的森林湖泊画面。背景是茂密且模糊的深绿色树林，占据了画面上半部分。前景是宽阔平静的水面，水色深沉。在画面中央偏下的位置，有两个极小的人影头部露出水面，仅能看到头顶和少许肩膀，彼此之间有一定距离。整体光线昏暗，呈现出一种压抑、神秘且静谧的视觉感受，人物在巨大的自然环境衬托下显得十分渺小。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T17:29:51-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Border_044.jpg","observed_dimensions":[1280,537],"source_thumbnail_dimensions":[500,210],"source_image_match_mae":0.485,"observed_resolution":"normal","observation_limits":[],"id":"VP-d460989d79559792","origin":"visual"},{"work_id":"src-bac6c76a669a62af","frame_id":"FG-1401adef3b21517e","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Border_056.jpg","source_page":"https://film-grab.com/2022/04/21/border/","scene":"画面中央站立着一名深色卷发人物，背对镜头，身穿深色上衣。背景是一栋带有白色立柱和深色大窗的宏伟建筑，整体色调阴冷昏暗。","analysis":"构图采用中心对称，人物背影占据画面下半部中央，仅可见头部及肩背部，身体其余部分被裁切。背景建筑横向延伸，白色圆柱与深色窗格形成垂直线条对比。光线极暗，呈现冷蓝色调，人物处于阴影中，轮廓模糊，与背景建筑形成明暗层次，营造出压抑、神秘的视觉氛围。","prompt":"这是一张冷色调的写实画面，整体笼罩在昏暗的蓝灰色光线中。画面正中央是一名背对镜头的人物，留着深色齐肩卷发，身穿深灰色或黑色上衣，仅露出头部和肩背部，身体其余部分位于画面之外。人物正对着一栋宏伟的建筑，建筑立面由多根白色圆柱支撑，柱间是巨大的深色玻璃窗格，窗户反射着微弱的环境光。建筑底部有低矮的围栏和基座。画面构图对称，人物处于前景中心，背景建筑占据大部分空间，光影对比强烈，人物处于暗部，背景建筑在微弱光线下显现轮廓，营造出一种阴郁、静谧且略带压抑的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T17:29:59-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Border_056.jpg","observed_dimensions":[1280,537],"source_thumbnail_dimensions":[500,210],"source_image_match_mae":0.47,"observed_resolution":"normal","observation_limits":[],"id":"VP-a9d542e801761eed","origin":"visual"}]};